package com.makers.loans.service;
import com.makers.loans.dto.*; import com.makers.loans.entity.*; import com.makers.loans.repository.UserRepository; import com.makers.loans.security.JwtService; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;}
 @Transactional public AuthResponse register(RegisterRequest r){if(users.existsByEmail(r.email())) throw new IllegalArgumentException("El correo ya está registrado"); User u=users.save(new User(r.email().toLowerCase(),encoder.encode(r.password()),Role.USER)); return new AuthResponse(jwt.generate(u.getEmail(),u.getRole().name()),u.getEmail(),u.getRole().name());}
 public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email().toLowerCase()).orElseThrow(()->new BadCredentialsException("Credenciales inválidas")); if(!encoder.matches(r.password(),u.getPassword())) throw new BadCredentialsException("Credenciales inválidas"); return new AuthResponse(jwt.generate(u.getEmail(),u.getRole().name()),u.getEmail(),u.getRole().name());}
}
